def solve(n, edges):
    visited = [False] * n
    count = 0

    def dfs(node):
        stack = [node]
        visited[node] = True
        while stack:
            current = stack.pop()
            for neighbor in range(n):
                if not visited[neighbor] and any(edge == [current, neighbor] or edge == [neighbor, current] for edge in edges):
                    visited[neighbor] = True
                    stack.append(neighbor)

    for i in range(n):
        if not visited[i]:
            dfs(i)
            count += 1

    return count
