def solve(nums, k):
    def _solve(nums, k, visited, index, count):
        # Base case: when all elements are included and count is tracked
        if count == len(nums):
            return
        # If the current element has not been processed yet
        if not visited[index]:
            # Mark as visited
            visited[index] = True
            # Recursively process the rest
            _solve(nums, k, visited, 0, count + 1)
            # Unmark for backtracking
            visited[index] = False
        else:
            # Skip the visited element
            _solve(nums, k, visited, index + 1, count)
    # Initialize visited array
    visited = [False] * len(nums)
    # Start processing from index 0
    _solve(nums, k, visited, 0, 0)
    # After processing, the visited array will have the k-th smallest element marked
    for i in range(len(nums)):
        if visited[i]:
            return nums[i]
    return None

