def solve(n, edges):
    def count_components(n, edges):
        graph = []
        for i in range(n - 1, 0, -1):
            graph.append([])
        for u, v in edges:
            graph[u].append(v)
            graph[v].append(u)
        visited = [False] * n
        count = 0
        for i in range(n):
            if not visited[i]:
                count += 1
                stack = [i]
                visited[i] = True
                while stack:
                    node = stack.pop()
                    for neighbor in graph[node]:
                        if not visited[neighbor]:
                            visited[neighbor] = True
                            stack.append(neighbor)
        return count
    return count_components(n, edges)
