def solve(n, edges):
    def find(parent, rank, x):
        if parent[x] == 0:
            return x
        return find(parent, rank, parent[x])
    def union(parent, rank, x, y):
        x_root = find(parent, rank, x)
        y_root = find(parent, rank, y)
        if x_root == y_root:
            return
        if rank[x_root] < rank[y_root]:
            parent[x_root] = y_root
        else:
            parent[y_root] = x_root
            if rank[x_root] == rank[y_root]:
                rank[x_root] += 1
    parent = [i for i in range(n)]
    rank = [1] * n
    for u, v in edges:
        union(parent, rank, u, v)
    roots = set()
    for i in range(n):
        roots.add(find(parent, rank, i))
    return len(roots)
