from collections import deque

def solve(n, edges):
    if n <= 0:
        return 0
    visited = set()
    for u, v in edges:
        if u < v:
            u, v = v, u
        if u not in visited:
            visited.add(u)
        if v not in visited:
            visited.add(v)
    components = 0
    for node in range(n):
        if node not in visited:
            components += 1
            queue = deque([node])
            visited.add(node)
            while queue:
                current = queue.popleft()
                for other in range(n):
                    if other != current and [current, other] in edges:
                        if other not in visited:
