                    return
                visited.add(u)
                for v in range(n):
                    if u != v and edges[u][v]:
                        dfs_helper(v, edges, visited)
                return

            visited = set()
            dfs_helper(u, edges, visited)
            return visited

        visited = set()
        components = 0
        for u in range(n):
            if u not in visited:
                components += 1
                comp = dfs(u)
                visited.update(comp)
        return components

