def solve(nums, k):
    def _heapify(arr, k):
        while True:
            if len(arr) < k:
                return
            else:
                p = (i - 1) // 2
                if arr[i] < arr[p]:
                    arr[i], arr[p] = arr[p], arr[i]
                    i = p
                else:
                    break
    def _heapify_down(arr, i, size):
        while True:
            left = 2 * i + 1
            right = 2 * i + 2
            smallest = i
            if left < size and arr[left] < arr[smallest]:
                smallest = left
            if right < size and arr[right] < arr[smallest]:
                smallest = right
            if smallest != i:
                arr[i], arr[smallest] = arr[smallest], arr[i]
                i = smallest
            else:
                break
    def _build_heap(arr):
        for i in range(len(arr) // 2 - 1, -1, -1):
            _heapify_down(arr, i, len(arr))
    def _heap_sort(arr):
        _build_heap(arr)
        for i in range(len(arr) - 1, 0, -1):
            arr[0], arr[i] = arr[i], arr[0]
            _heapify_down(arr, 0, i)
    _heap_sort(nums)
    return nums[k - 1]
