        while parent[u] != u:
            parent[u] = parent[parent[u]]  # Path compression
            u = parent[u]
        return u

    def union(u, v):
        root_u = find(u)
        root_v = find(v)
        if root_u != root_v:
            parent[root_v] = root_u  # Merge the two sets

    for u, v in edges:
        union(u, v)

    # Count the number of unique roots (connected components)
    return len({find(i) for i in range(n)})
