def solve():
    from collections import deque

    def bfs(grid, start, end):
        rows, cols = len(grid), len(grid[0])
        directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
        visited = [[False for _ in range(cols)] for _ in range(rows)]
        queue = deque([(start[0], start[1], [start])])
        visited[start[0]][start[1]] = True

        while queue:
            x, y, path = queue.popleft()
            if (x, y) == end:
                return path
            for dx, dy in directions:
                nx, ny = x + dx, y + dy
                if 0 <= nx < rows and 0 <= ny < cols and not visited[nx][ny] and grid[nx][ny] != '#':
                    visited[nx][ny] = True
                    new_path = path + [(nx, ny)]
                    queue.append((nx, ny, new_path))
        return None

    def is_valid(grid, pos):
        x, y = pos
        return 0 <= x < len(grid) and 0 <= y < len(grid[0]) and grid[x][y] != '#'

    def find_path(grid, start, end):
        if not is_valid(grid, start) or not is_valid(grid, end):
            return None
        if start == end:
            return [start]
        path = bfs(grid, start, end)
        return path if path else None

    def parse_input(grid_str):
        grid = [list(line) for line in grid_str.strip().split('\n')]
        return grid

    def main():
        import sys
        input_lines = sys.stdin.read().split('\n')
        grid_str = '\n'.join(input_lines)
        grid = parse_input(grid_str)
        start = None
        end = None
        for i, row in enumerate(grid):
            for j, cell in enumerate(row):
                if cell == 'S':
                    start = (i, j)
                elif cell == 'E':
                    end = (i, j)
        if not start or not end:
            return []
        path = find_path(grid, start, end)
        return path if path else []

    return main()
