    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    # Priority queue for Dijkstra's algorithm
    pq = [(0, start[0], start[1])]
    visited = set()
    parent = {}

    while pq:
        dist, r, c = heapq.heappop(pq)
        if (r, c) == goal:
            # Reconstruct path
            path = []
            while (r, c) != start:
                path.append((r, c))
                r, c = parent[(r, c)]
            path.append(start)
            return path[::-1]
        if (r, c) in visited:
            continue
        visited.add((r, c))
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if is_valid(nr, nc):
                if (nr, nc) not in visited:
                    parent[(nr, nc)] = (r, c)
                    heapq.heappush(pq, (dist + 1, nr, nc))

    return []
