def solve(n, edges):
    from collections import deque

    def build_adjacency_list(n, edges):
        adj = [[] for _ in range(n)]
        for u, v in edges:
            adj[u].append(v)
            adj[v].append(u)
        return adj

    def bfs(start, adj, visited):
        queue = deque([start])
        visited.add(start)
        while queue:
            node = queue.popleft()
            for neighbor in adj[node]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append(neighbor)

    adj = build_adjacency_list(n, edges)
    visited = set()
    components = 0

    for i in range(n):
        if i not in visited:
            components += 1
            bfs(i, adj, visited)

    return components
